&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;51&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;52&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Technical and Analytical Skills&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
