&lt;div class=&quot;rich-text-paragraph&quot; data-eleid=&quot;57&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;58&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Soft Skills and Leadership&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;ul class=&quot;richTextDocs-unOrderList richTextDocs-unOrderList-disc&quot; data-eleid=&quot;59&quot;&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;60&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;61&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Exceptional communication, negotiation, and relationship-building abilities, with experience managing VIPs such as HNWI, family offices, proptrading desks.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;62&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;63&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Goal-oriented mindset with a history of exceeding KPIs in user acquisition, retention, and revenue targets through data-driven strategies.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;64&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;65&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Compliance and Market Knowledge&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
